namespace FileMonitoring.Api.Domain;

public class Policy { public Guid Id { get; set; } public string Name { get; set; } = ""; public bool Enabled { get; set; } = true; public string Action { get; set; } = "Alert"; public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public List<PolicyRule> Rules { get; set; } = []; }
public class PolicyRule { public Guid Id { get; set; } public Guid PolicyId { get; set; } public string Field { get; set; } = ""; public string Operator { get; set; } = ""; public string Value { get; set; } = ""; }
public class Alert { public Guid Id { get; set; } public Guid? FileEventId { get; set; } public Guid? PolicyId { get; set; } public string Severity { get; set; } = "Medium"; public string Message { get; set; } = ""; public string Status { get; set; } = "Open"; public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; }
public class Notification { public Guid Id { get; set; } public string TargetType { get; set; } = "All"; public Guid? TargetId { get; set; } public string Title { get; set; } = ""; public string Message { get; set; } = ""; public string Status { get; set; } = "Pending"; public Guid? CreatedBy { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset? DeliveredAt { get; set; } }
public class AuditLog { public long Id { get; set; } public string Actor { get; set; } = ""; public string Action { get; set; } = ""; public string? Entity { get; set; } public string? EntityId { get; set; } public string? Details { get; set; } public string? IpAddress { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; }
